/**
 * A dashboard counter: an icon, a big number, a caption. With `href` the whole tile is a link, without it the
 * tile is a plain figure.
 */
import { type ReactNode } from "react";
import { Box, IconBadge, Link, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { urlOf } from "../utils";

export type StatTileProps = {
  label: string;
  value: string | number;
  icon: string;
  href?: string;
  hint?: string;
};

export function StatTile({ label, value, icon, href, hint }: StatTileProps) {
  return (
    <Box className="min-w-0" data-slot="stat-tile">
      {href ? (
        <Link
          href={urlOf(href)}
          variant="block"
          className={"flex min-w-0 flex-col gap-4 rounded bg-card p-6 text-foreground no-underline inset-ring inset-ring-border " +
            "hover:bg-muted"}
        >
          <Box className="flex items-center justify-between gap-2">
            <Text className="m-0 text-xs font-bold text-muted-foreground">
              {label}
            </Text>
            <IconBadge size="sm">
              <LucideIcon name={icon} size={16} />
            </IconBadge>
          </Box>
          <Text size="2xl" weight="bold" className="m-0 leading-8">
            {value}
          </Text>
          {hint ? (
            <Text className="m-0 text-xs font-medium text-muted-foreground">
              {hint}
            </Text>
          ) : null}
        </Link>
      ) : (
        <Box className={"flex min-w-0 flex-col gap-4 rounded bg-card p-6 text-foreground inset-ring inset-ring-border"}>
          <Box className="flex items-center justify-between gap-2">
            <Text className="m-0 text-xs font-bold text-muted-foreground">
              {label}
            </Text>
            <IconBadge size="sm">
              <LucideIcon name={icon} size={16} />
            </IconBadge>
          </Box>
          <Text size="2xl" weight="bold" className="m-0 leading-8">
            {value}
          </Text>
          {hint ? (
